/**
 * CompositeEditorAction is an abstract class that should be extended for any action that is to be 
 * associated with a composite editor.
 * <p>
 * Note: Any new actions must be registered in the editor manager via the actions's name.
 */
abstract public class CompositeEditorTableAction : DockingAction {

	static readonly string MAIN_ACTION_GROUP = "0_MAIN_EDITOR_ACTION";
	static readonly string UNDOREDO_ACTION_GROUP = "1_UNDOREDO_EDITOR_ACTION";
	static readonly string BASIC_ACTION_GROUP = "2_BASIC_EDITOR_ACTION";
	static readonly string DATA_ACTION_GROUP = "3_DATA_EDITOR_ACTION";
	static readonly string COMPONENT_ACTION_GROUP = "4_COMPONENT_EDITOR_ACTION";
	static readonly string BITFIELD_ACTION_GROUP = "5_COMPONENT_EDITOR_ACTION";

	protected CompositeEditorProvider<object,object> provider;
	protected CompositeEditorModel<object> model;
	protected string tooltip;
	protected ImageIcon icon;
	protected ActionListener listener;
	protected string displayString;
	protected string actionCommand;
	protected JButton button; // corresponding JButton for this action
	protected KeyStroke keystroke;
	protected Plugin plugin;
	protected PluginTool tool;

	// note: Only call this constructor if you know you do not want to use the shared editor prefix;
	//       If you call this, then you must manage your own menu/popup/toolbar data installation
	protected CompositeEditorTableAction(CompositeEditorProvider<object,object> provider, string name) : base(name, provider.plugin.getName())
    {
		init(provider);
	}

	public CompositeEditorTableAction(CompositeEditorProvider<object,object> provider, string name,
			string group,
			string[] popupPath, string[] menuPath, Icon icon) : base(name, provider.plugin.getName(), KeyBindingType.SHARED)
    {
		init(provider);
		if (menuPath != null) {
			setMenuBarData(new MenuData(menuPath, icon, group));
		}
		if (popupPath != null) {
			setPopupMenuData(new MenuData(popupPath, icon, group));
		}
		if (icon != null) {
			setToolBarData(new ToolBarData(icon, group));
		}
	}

	private void init(CompositeEditorProvider<object,object> editorProvider) {
		this.provider = editorProvider;
		this.model = provider.getModel();
		this.plugin = provider.plugin;
		this.tool = plugin.getTool();
		string helpAnchor = provider.getHelpName() + "_" + getHelpName();
		setHelpLocation(new HelpLocation(provider.getHelpTopic(), helpAnchor));
	}

